/// <summary>
/// PricingAttribute of table <c>WHSInventTable</c> field FilterGroup.
/// </summary>
/// [UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeWHSInventTableFilterGroup extends UPSPricingAttributeWHSInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(WHSInventTable, FilterGroup);
}

public Set getAllowedValues()
{
    var            ret = new Set(Types::String);
    WHSInventTable wHSInventTable;

    while select wHSInventTable
        group by FilterGroup
    {
        if (! ret.in(wHSInventTable.FilterGroup))
        {
            ret.add(wHSInventTable.FilterGroup);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(WHSInventTable, FilterGroup));
    qbr.value(queryValue(_value));
}
